<script setup>
import { onMounted } from 'vue'
import { useAuthStore } from '@/stores/authStore'
import { useNotificationStore } from '@/stores/notificationStore'

const auth = useAuthStore()
const notifications = useNotificationStore()

function formatDate(value) {
  const date = new Date(value)
  return Number.isNaN(date.getTime())
    ? value
    : date.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' })
}

onMounted(() => notifications.load())
</script>

<template>
  <section class="page-panel">
    <p class="eyebrow">User</p>
    <h1>Profile</h1>
    <div class="profile-grid">
      <span>Username</span>
      <strong>{{ auth.user?.username }}</strong>
      <span>Email</span>
      <strong>{{ auth.user?.email }}</strong>
      <span>Role</span>
      <strong>{{ auth.user?.role }}</strong>
    </div>

    <!-- Notifications now live inside the profile page, marked with a bell icon -->
    <div class="notifications-section">
      <div class="notifications-head">
        <span class="notifications-bell" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"
            stroke-linecap="round" stroke-linejoin="round">
            <path d="M18 8a6 6 0 1 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9" />
            <path d="M10 21h4" />
          </svg>
          <span v-if="notifications.unreadCount" class="notifications-bell__dot"></span>
        </span>
        <div class="notifications-head__text">
          <h2>Notifications</h2>
          <p>Upload request updates and administrator decisions appear here.</p>
        </div>
        <span v-if="notifications.unreadCount" class="notification-badge">
          {{ notifications.unreadCount }} unread
        </span>
      </div>

      <p v-if="notifications.loading">Loading notifications...</p>
      <p v-else-if="notifications.error" class="form-error">{{ notifications.error }}</p>
      <div v-else-if="notifications.items.length" class="notification-list">
        <article
          v-for="notification in notifications.items"
          :key="notification.id"
          class="notification-card"
          :class="{ 'notification-card--unread': !notification.isRead }"
        >
          <div>
            <h3>{{ notification.title }}</h3>
            <p>{{ notification.message }}</p>
            <small>{{ formatDate(notification.createdAt) }}</small>
          </div>
          <button
            class="button button--ghost button--small"
            type="button"
            :disabled="notification.isRead"
            @click="notifications.markRead(notification.id)"
          >
            {{ notification.isRead ? 'Read' : 'Mark read' }}
          </button>
        </article>
      </div>
      <div v-else class="empty-state">
        <h3>No notifications</h3>
        <p>Updates will appear here when your upload request changes status.</p>
      </div>
    </div>
  </section>
</template>

